-- Append after existing rollback-only regression fixtures. Never commit fixtures.
reset role;
insert into public.saved_addresses(address_id,customer_id,label,address_line,city,state,postcode,coordinates)
values('eeeeeeee-0000-4000-8000-000000000001',pg_temp.fixture_id('customer_profile'),'AI fixture','123 Test Street','Regression City','Selangor','50000','3,101')
on conflict(address_id) do nothing;
create temporary table ai_test_values(name text primary key,value jsonb) on commit drop;
grant all on ai_test_values to authenticated;
create function pg_temp.ai_value(k text) returns jsonb language sql stable as $$select value from pg_temp.ai_test_values where name=k$$;
set local role authenticated;
select pg_temp.login_as('customer_auth','aal1');
insert into ai_test_values values('chat',public.customer_ai_create_conversation('aaaaaaaa-1234-4234-8234-000000000001'));
select pg_temp.test_assert('AI chat creation retry idempotent',public.customer_ai_create_conversation('aaaaaaaa-1234-4234-8234-000000000001')->>'id'=pg_temp.ai_value('chat')->>'id');
select pg_temp.test_assert('AI list returns owned chat',jsonb_array_length(public.customer_ai_conversations())=1);
insert into ai_test_values values('turn',public.customer_ai_begin_turn((pg_temp.ai_value('chat')->>'id')::uuid,'aaaaaaaa-1234-4234-8234-000000000002','Help me choose a cleaner'));
select pg_temp.test_error('AI concurrent duplicate blocked',$$select public.customer_ai_begin_turn((pg_temp.ai_value('chat')->>'id')::uuid,'aaaaaaaa-1234-4234-8234-000000000002','Help me choose a cleaner')$$,'55P03');
select pg_temp.test_error('AI changed retry payload rejected',$$select public.customer_ai_begin_turn((pg_temp.ai_value('chat')->>'id')::uuid,'aaaaaaaa-1234-4234-8234-000000000002','Different message')$$,'P0001');
select pg_temp.test_error('AI user cannot forge model response',$$select public.ai_finish_turn((pg_temp.ai_value('turn')->>'turn_id')::uuid,(pg_temp.ai_value('turn')->>'lease')::uuid,pg_temp.fixture_id('customer_auth'),'Forged','[]')$$,'42501');
select pg_temp.test_error('AI tables not client writable',$$insert into private.ai_messages(conversation_id,turn_id,role,content) values((pg_temp.ai_value('chat')->>'id')::uuid,(pg_temp.ai_value('turn')->>'turn_id')::uuid,'assistant','Forged')$$,'42501');
reset role;
select public.ai_finish_turn((pg_temp.ai_value('turn')->>'turn_id')::uuid,(pg_temp.ai_value('turn')->>'lease')::uuid,pg_temp.fixture_id('customer_auth'),'Here are your options.','[]');
set local role authenticated;
select pg_temp.test_assert('AI completed retry replays reply',(public.customer_ai_begin_turn((pg_temp.ai_value('chat')->>'id')::uuid,'aaaaaaaa-1234-4234-8234-000000000002','Help me choose a cleaner')->>'replay')::boolean);
select pg_temp.test_assert('AI history has one user one assistant',jsonb_array_length(public.customer_ai_messages((pg_temp.ai_value('chat')->>'id')::uuid))=2);
select pg_temp.test_error('AI foreign image rejected',$$select public.customer_ai_begin_turn((pg_temp.ai_value('chat')->>'id')::uuid,'aaaaaaaa-1234-4234-8234-000000000003','Photo','other/other/photo.jpg')$$,'42501');
insert into ai_test_values values('draft',public.customer_ai_stage_action((pg_temp.ai_value('chat')->>'id')::uuid,'booking',jsonb_build_object('service_id',pg_temp.fixture_id('service'),'address_id','eeeeeeee-0000-4000-8000-000000000001','date',(now() at time zone 'Asia/Kuala_Lumpur')::date+30,'time','09:00','instructions','AI fixture')));
select pg_temp.test_assert('AI draft price comes from database',(pg_temp.ai_value('draft')->'payload'->>'quote')::numeric=180);
reset role;
update private.ai_messages set actions=jsonb_build_array(pg_temp.ai_value('draft')) where turn_id=(pg_temp.ai_value('turn')->>'turn_id')::uuid and role='assistant';
update public.services set base_price=base_price+10 where service_id=pg_temp.fixture_id('service');
set local role authenticated;
select pg_temp.test_error('AI changed quote requires fresh consent',$$select public.customer_ai_confirm_action((pg_temp.ai_value('draft')->>'id')::uuid)$$,'P0001');
reset role;
update public.services set base_price=base_price-10 where service_id=pg_temp.fixture_id('service');
update public.saved_addresses set address_line='Changed address' where address_id='eeeeeeee-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.test_error('AI changed address requires fresh consent',$$select public.customer_ai_confirm_action((pg_temp.ai_value('draft')->>'id')::uuid)$$,'P0001');
reset role;
update public.saved_addresses set address_line='123 Test Street' where address_id='eeeeeeee-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.test_error('AI client cannot inject price',$$select public.customer_ai_stage_action((pg_temp.ai_value('chat')->>'id')::uuid,'booking',(pg_temp.ai_value('draft')->'payload')||'{"quote":1}')$$,'P0001');
insert into ai_test_values values('booking',public.customer_ai_confirm_action((pg_temp.ai_value('draft')->>'id')::uuid));
select pg_temp.test_assert('AI confirm creates Pending only',pg_temp.ai_value('booking')->>'booking_status'='Pending');
select pg_temp.test_assert('AI double confirmation one booking',public.customer_ai_confirm_action((pg_temp.ai_value('draft')->>'id')::uuid)->>'booking_id'=pg_temp.ai_value('booking')->>'booking_id');
select pg_temp.test_assert('AI history reflects confirmed action',public.customer_ai_messages((pg_temp.ai_value('chat')->>'id')::uuid)->1->'actions'->0->>'status'='done');
insert into ai_test_values values('default',public.customer_ai_stage_action((pg_temp.ai_value('chat')->>'id')::uuid,'default_address','{"address_id":"eeeeeeee-0000-4000-8000-000000000001"}'));
select public.customer_ai_confirm_action((pg_temp.ai_value('default')->>'id')::uuid);
select pg_temp.test_error('AI cannot stage payment',$$select public.customer_ai_stage_action((pg_temp.ai_value('chat')->>'id')::uuid,'pay','{}')$$,'P0001');
select pg_temp.login_as('provider_auth','aal1');
select pg_temp.test_error('AI provider denied customer history',$$select public.customer_ai_messages((pg_temp.ai_value('chat')->>'id')::uuid)$$,'42501');
select pg_temp.login_as('super_auth','aal1');
select pg_temp.test_error('AI other account cannot confirm draft',$$select public.customer_ai_confirm_action((pg_temp.ai_value('draft')->>'id')::uuid)$$,'42501');
select pg_temp.login_as('customer_auth','aal1');
select public.customer_ai_delete_conversation((pg_temp.ai_value('chat')->>'id')::uuid);
select pg_temp.test_error('AI deleted chat inaccessible',$$select public.customer_ai_messages((pg_temp.ai_value('chat')->>'id')::uuid)$$,'42501');
select pg_temp.test_assert('AI deletion retains actual booking',public.customer_booking_detail((pg_temp.ai_value('booking')->>'booking_id')::uuid)->>'booking_status'='Pending');
insert into ai_test_values values('erase_chat',public.customer_ai_create_conversation('aaaaaaaa-1234-4234-8234-000000000010'));
select public.customer_ai_begin_turn((pg_temp.ai_value('erase_chat')->>'id')::uuid,'aaaaaaaa-1234-4234-8234-000000000011','Erase my private text');
reset role;
insert into private.customer_deletions(auth_user_id,user_id) values(pg_temp.fixture_id('customer_auth'),(select user_id from public.customer_profiles where customer_id=pg_temp.fixture_id('customer_profile')));
select pg_temp.test_assert('AI account deletion erases conversation content',not exists(select 1 from private.ai_messages where conversation_id=(pg_temp.ai_value('erase_chat')->>'id')::uuid));
select pg_temp.test_assert('AI account deletion clears pending turn text',not exists(select 1 from private.ai_turns where conversation_id=(pg_temp.ai_value('erase_chat')->>'id')::uuid and message<>''));
select pg_temp.test_assert('AI deletion erases message content',not exists(select 1 from private.ai_messages where conversation_id=(pg_temp.ai_value('chat')->>'id')::uuid));
select pg_temp.test_error('AI late worker cannot restore deleted chat',$$select public.ai_finish_turn((pg_temp.ai_value('turn')->>'turn_id')::uuid,(pg_temp.ai_value('turn')->>'lease')::uuid,pg_temp.fixture_id('customer_auth'),'Late','[]')$$,'42501');
set local role anon;
select pg_temp.test_error('AI anonymous denied',$$select public.customer_ai_conversations()$$,'42501');
reset role;
